public class RMarketJson_Bybit_SetCollateral_Request
{
    private str coin;
    private str collateralSwitch;

}

Method.Source:
/// <summary> Получает или устанавливает валюту для изменения залогового режима </summary>
/// <param name="_coin"> Код валюты (например, "USDT", "BTC") </param>
/// <returns> Код валюты </returns>
[DataMember('coin')]
public str parmCoin(str _coin = coin)
{
    coin = _coin;
    return coin;
}

/// <summary> Получает или устанавливает режим залога ["ON", "OFF"] </summary>
/// <param name="_collateralSwitch"> Включение/выключение залогового режима </param>
/// <returns> Статус залогового режима </returns>
[DataMember('collateralSwitch')]
public str parmCollateralSwitch(str _collateralSwitch = collateralSwitch)
{
    collateralSwitch = _collateralSwitch;
    return collateralSwitch;
}

/// <summary>Формирует JSON-тело запроса</summary>
/// <returns>Строка с JSON-запросом</returns>
public str jsonRequest()
{
    str ret = FormJsonSerializer::serializeClass(this);
    return ret;
}
